def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def checked(raw, record):
    if len(raw) != record["bytes"] or digest(raw) != record["sha256"]:
        raise ValueError("Complete source bytes differ: " + record["name"])
    if len(raw) >= 100000:
        raise ValueError("Do not truncate a complete source to meet the small-source limit")
    return raw.decode("utf-8")


def apply_hunks(source, hunks, inverse=False):
    lines = source.split("\n")
    for hunk in reversed(hunks):
        start = hunk["new_start"] if inverse else hunk["old_start"]
        previous = hunk["new_lines"] if inverse else hunk["old_lines"]
        replacement = hunk["old_lines"] if inverse else hunk["new_lines"]
        if lines[start:start + len(previous)] != previous:
            raise ValueError("The complete exact text hunk differs from its pinned parent")
        lines[start:start + len(previous)] = replacement
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source-directory", type=Path, required=True)
    parser.add_argument("--output-directory", type=Path, required=True)
    args = parser.parse_args()
    origin = args.source_directory.resolve()
    destination = args.output_directory.resolve()
    if origin == destination:
        raise ValueError("Use a separate directory for the independent complete sources")
    parents = {}
    for item in PAYLOAD["derivations"]:
        path = origin / item["parent"]["name"]
        parents[item["key"]] = checked(path.read_bytes(), item["parent"])
    outputs = []
    for item in PAYLOAD["new_sources"]:
        raw = item["source"].encode("utf-8")
        checked(raw, item["record"])
        outputs.append((item["record"], raw))
    for item in PAYLOAD["derivations"]:
        original = parents[item["key"]]
        result = apply_hunks(original, item["hunks"])
        raw = result.encode("utf-8")
        checked(raw, item["output"])
        if apply_hunks(result, item["hunks"], inverse=True) != original:
            raise ValueError("The exact complete reverse construction did not retain the parent")
        outputs.append((item["output"], raw))
    # All seven full bodies are constructed before any output is written.
    destination.mkdir(parents=True, exist_ok=True)
    for record, raw in outputs:
        path = destination / record["name"]
        if path.exists() and path.read_bytes() != raw:
            raise ValueError("Do not replace a different existing complete source: " + str(path))
    for record, raw in outputs:
        path = destination / record["name"]
        path.write_bytes(raw)
        checked(path.read_bytes(), record)
    for item in PAYLOAD["derivations"]:
        checked((origin / item["parent"]["name"]).read_bytes(), item["parent"])
    print(json.dumps(dict(schema=PAYLOAD["schema"], parent_commit=PAYLOAD["parent_commit"],
        complete_source_count=len(outputs), complete_output_records=[record for record, _ in outputs],
        full_forward_and_reverse_text_construction=True,
        scientific_import_or_execution=False, solver_admission_gate=False), sort_keys=True))


if __name__ == "__main__":
    main()
